 * 仓储段概要响应。限值单位为摄氏度(℃)，createdAt 为 UTC instant。
 */
public record SegmentResponse(
        String batchKey,
        String segmentKey,
        BigDecimal upperLimit,
        BigDecimal lowerLimit,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 修改仓储段温度限值请求，单位℃；仅影响修改之后登记的新读数，
 * 历史偏差保留触发时的限值快照，不回写。
 */
public record UpdateLimitsRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "upperLimit 不能为空，单位℃") BigDecimal upperLimit,
        @NotNull(message = "lowerLimit 不能为空，单位℃") BigDecimal lowerLimit
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 仓储温度读数登记请求。readingTime 为采集时刻（ISO-8601 UTC），temperature 为摄氏度(℃)；
 * requestId 在请求路径外由请求体提供，同键重放返回首次结果，同键换温度/时刻/仓储段返回 409。
 */
public record RegisterReadingRequest(
        @NotBlank(message = "requestId 不能为空") String requestId,
        @NotNull(message = "readingTime 不能为空，UTC 采集时刻") Instant readingTime,
        @NotNull(message = "temperature 不能为空，单位℃") BigDecimal temperature
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.DeviationStatus;
import com.example.starter.batch.DeviationType;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 仓储温度偏差事件响应。
 * 温度与限值快照单位均为摄氏度(℃)，时刻均为 UTC。
 *
 * @param observedTemperatureCelsius 触发读数温度；缺测偏差取间隔后一读数温度
 * @param upperLimitSnapshot         触发时段上限快照，限值后续修改不回写
 * @param lowerLimitSnapshot         触发时段下限快照，限值后续修改不回写
 * @param gapStart                   缺测区间起点（前一读数时刻），越界偏差为 null
 * @param gapEnd                     缺测区间终点（间隔大于30分钟的后一读数时刻），越界偏差为 null
 * @param disposedAt                 解除时刻，未处置为 null
 * @param confirmations              处置确认列表（处置人、角色、备注、时刻）
 */
public record DeviationResponse(
        String deviationKey,
        String batchKey,
        String segmentKey,
        DeviationType type,
        DeviationStatus status,
        int version,
        BigDecimal observedTemperatureCelsius,
        BigDecimal upperLimitSnapshot,
        BigDecimal lowerLimitSnapshot,
        Instant gapStart,
        Instant gapEnd,
        Instant createdAt,
        Instant disposedAt,
        List<ConfirmationResponse> confirmations
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.ApprovalRole;

import java.time.Instant;

/**
 * 偏差处置确认响应。两名不同角色（QUALITY/OPERATIONS）且不同操作人
 * 针对同一偏差版本各确认一次后偏差解除；note 为空表示未填写备注。
 */
public record ConfirmationResponse(
        String deviationKey,
        int version,
        String actorId,
        ApprovalRole role,
        String note,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * 温度读数登记响应：读数本体 + 本次读数触发的偏差事件（越界/缺测，可能同时触发两类）
 * + 登记后批次门禁状态。GATE_CLOSED 表示批次存在未处置偏差，禁止放行、拆分和合批。
 */
public record ReadingResponse(
        String batchKey,
        String segmentKey,
        String requestId,
        Instant readingTime,
        BigDecimal temperatureCelsius,
        List<DeviationResponse> deviations,
        String gateStatus,
        int openDeviationCount,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 偏差处置确认请求体。version 必须与偏差当前版本一致（否则 409）；
 * 处置人与角色通过 X-Actor-Id / X-Approval-Role 请求头提供。
 */
public record ConfirmDeviationRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotNull(message = "version 不能为空") Integer version,
        String note
) {
}

