package com.example.starter.batch.dto;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 时刻查询中的原始读数条目，按采集时刻升序。
 * outOfLimit 表示该读数相对其登记时段限值越界；outOfLimitDeviationKey 为对应偏差键（无则为 null）。
 */
public record ReadingEntry(
        String requestId,
        Instant readingTime,
        BigDecimal temperatureCelsius,
        boolean outOfLimit,
        String outOfLimitDeviationKey,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import java.time.Instant;

/**
 * 相邻读数区间条目，按起点时刻升序；gapMinutes 为相邻采集时刻间隔（分钟，保留小数）。
 * missing=true 表示间隔严格大于 30 分钟的缺测区间，missingDeviationKey 为对应缺测偏差键。
 */
public record IntervalEntry(
        String fromRequestId,
        String toRequestId,
        Instant start,
        Instant end,
        long gapSeconds,
        boolean missing,
        String missingDeviationKey
) {
}

package com.example.starter.batch.dto;

import java.math.BigDecimal;
import java.util.List;

/**
 * 仓储段时刻查询视图：原始读数、相邻区间（标注缺测）、全部偏差（含处置人与确认记录）
 * 与当前门禁状态。历史偏差携带触发时限值快照，不随后续限值修改而回写。
 */
public record StorageTimelineResponse(
        String batchKey,
        String segmentKey,
        BigDecimal upperLimit,
        BigDecimal lowerLimit,
        List<ReadingEntry> readings,
        List<IntervalEntry> intervals,
        List<DeviationResponse> deviations,
        String gateStatus,
        int openDeviationCount
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 合批请求体。2～5 个当前 RELEASED 且无未处置偏差的父批合并为一个 QUARANTINED 子批；
 * 父批必须属于同一产品编码，任一父批存在未处置偏差时整单失败、不落任何数据。
 */
public record MergeRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "childKey 不能为空") String childKey,
        @NotBlank(message = "childBatchNo 不能为空") String childBatchNo,
        @NotNull(message = "parents 不能为空")
        @Size(min = 2, max = 5, message = "parents 必须包含 2～5 个父批")
        List<@NotBlank(message = "父批 batchKey 不能为空") String> parents
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.time.Instant;
import java.util.List;

/**
 * 合批响应：新子批概要（初始 QUARANTINED）与参与合批的父批键（按请求顺序）。
 * 子批继承父批产品编码与必做检验项（并集，按父批顺序首次出现），不继承检验、批准与仓储记录。
 */
public record MergeResponse(
        String childKey,
        String childBatchNo,
        String productCode,
        BatchStatus status,
        List<String> parentKeys,
        List<String> requiredTests,
        Instant createdAt
) {
}

