    // ---------- 越界偏差与 RELEASE_HOLD ----------

    @Test
    void outOfLimitReading_onReleasedBatch_setsHoldAndBlocksUntilDisposal() throws Exception {
        String batchKey = "BK-HOLD-" + unique();
