        JsonNode tl = timeline(batchKey, "SEG-TL");
        assertEquals(3, tl.path("readings").size());
        assertEquals("REQ-TL-1", tl.path("readings").get(0).path("requestId").asText());
        assertEquals(2, tl.path("intervals").size());
